class Solution {
public:
    vector<string> findWords(vector<string>& words) {
        int row[26];
        string r1 = "qwertyuiop";
        string r2 = "asdfghjkl";
        string r3 = "zxcvbnm";
        for (char c : r1) row[c - 'a'] = 0;
        for (char c : r2) row[c - 'a'] = 1;
        for (char c : r3) row[c - 'a'] = 2;

        vector<string> result;
        for (const string& w : words) {
            int targetRow = row[tolower(w[0]) - 'a'];
            bool same = true;
            for (char c : w) {
                if (row[tolower(c) - 'a'] != targetRow) {
                    same = false;
                    break;
                }
            }
            if (same) result.push_back(w);
        }
        return result;
    }
};
